        .containsExactly("ws-ai", "ws-cloud", "ev-night");
    assertThat(configuration().options()).hasSize(4);
    assertThat(configuration().consents()).extracting(ConsentDefinition::id).containsExactly("privacy", "photo");
  }

  @Test
  void findsOptionsAndConsentsById() {
    ConferenceConfiguration config = configuration();

    assertThat(config.option("meal-old")).map(ConferenceOption::name).contains("Old meal");
    assertThat(config.option("none")).isEmpty();
    assertThat(config.consent("photo")).map(ConsentDefinition::mandatory).contains(false);
    assertThat(config.consent("none")).isEmpty();
  }

  @Test
  void listsAreCopied() {
    List<ConferenceOption> options = new ArrayList<>(List.of(option("a", OptionCategory.MEAL)));
    ConferenceConfiguration config = new ConferenceConfiguration(options, CONSENTS);
    options.clear();

    assertThat(config.options()).hasSize(1);
  }

  @Test
  void rejectsDuplicateOptionId() {
    assertInvalid(
        List.of(option("a", OptionCategory.MEAL), option("a", OptionCategory.EVENT)),
        CONSENTS,
        "duplicate option id a");
  }

  @ParameterizedTest
  @ValueSource(strings = {"", "A", "-a", "a_b", "a b", "ä"})
  void rejectsInvalidOptionId(String id) {
    assertInvalid(List.of(option(id, OptionCategory.MEAL)), CONSENTS, "invalid option id " + id);
  }

  @Test
  void acceptsIdsOfOneToSixtyFourCharacters() {
    String longest = "a" + "-".repeat(63);

    assertThat(
            new ConferenceConfiguration(
                    List.of(option("0", OptionCategory.MEAL), option(longest, OptionCategory.MEAL)),
                    CONSENTS)
                .options())
        .hasSize(2);
    assertInvalid(
        List.of(option(longest + "a", OptionCategory.MEAL)),
        CONSENTS,
        "invalid option id " + longest + "a");
  }

  @Test
  void rejectsNullOptionId() {
    assertInvalid(
        List.of(new ConferenceOption(null, "n", OptionCategory.MEAL, true, Set.of(RegistrationType.STUDENT))),
        CONSENTS,
        "invalid option id null");
  }

  @Test
  void rejectsMissingOrBlankName() {
    for (String name : new String[] {null, " "}) {
      assertInvalid(
          List.of(new ConferenceOption("a", name, OptionCategory.MEAL, true, Set.of(RegistrationType.STUDENT))),
          CONSENTS,
          "missing name of option a");
    }
  }

  @Test
  void rejectsMissingCategory() {
    assertInvalid(
        List.of(new ConferenceOption("a", "n", null, true, Set.of(RegistrationType.STUDENT))),
        CONSENTS,
        "missing category of option a");
  }

  @Test
  void rejectsOptionAvailableToNobody() {
    assertInvalid(
        List.of(new ConferenceOption("a", "n", OptionCategory.MEAL, true, Set.of())),
        CONSENTS,
        "option a available to nobody");
  }

  @Test
  void rejectsDuplicateConsentId() {
    assertInvalid(
        List.of(),
        List.of(new ConsentDefinition("p", "x", true), new ConsentDefinition("p", "y", false)),
        "duplicate consent id p");
  }

  @Test
  void rejectsInvalidConsentIdAndMissingText() {
    assertInvalid(List.of(), List.of(new ConsentDefinition("P", "x", true)), "invalid consent id P");
    assertInvalid(List.of(), List.of(new ConsentDefinition("p", "", true)), "missing text of consent p");
    assertInvalid(List.of(), List.of(new ConsentDefinition("p", null, true)), "missing text of consent p");
  }
}

package si.konferenca.registration.domain;

import static org.assertj.core.api.Assertions.assertThat;
import static si.konferenca.registration.domain.DomainFixtures.configuration;

import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class SearchCriteriaTest {

  private static SearchCriteria.Parsed parse(String text, String type, String option, String page) {
    return SearchCriteria.parse(text, type, option, page, configuration());
  }

  private static SearchCriteria valid(String text, String type, String option, String page) {
    SearchCriteria.Parsed parsed = parse(text, type, option, page);
    assertThat(parsed.errors()).isEmpty();
    return parsed.criteria();
  }

  @Test
  void absentOrEmptyParametersMeanEverythingOnPageOne() {
    SearchCriteria expected = new SearchCriteria("", Optional.empty(), Optional.empty(), 1);

    assertThat(valid(null, null, null, null)).isEqualTo(expected);
    assertThat(valid("", "", "", "")).isEqualTo(expected);
    assertThat(expected.offset()).isZero();
  }

  @Test
  void textIsTrimmedAndLowerCased() {
    assertThat(valid("  ČeŠ Žar  ", null, null, null).text()).isEqualTo("češ žar");
  }

  @Test
  void textLimitAppliesToTheRawText() {
    assertThat(valid("a".repeat(100), null, null, null).text()).hasSize(100);
    SearchCriteria.Parsed parsed = parse(" " + "a".repeat(100), null, null, null);

    assertThat(parsed.criteria()).isNull();
    assertThat(parsed.errors()).containsExactly(new FieldError("text", "At most 100 characters."));
  }

  @Test
  void typeAndConfiguredOptionAreParsed() {
    SearchCriteria criteria = valid(null, "STUDENT", "meal-old", "3");

    assertThat(criteria.type()).contains(RegistrationType.STUDENT);
    assertThat(criteria.option()).contains("meal-old");
    assertThat(criteria.page()).isEqualTo(3);
    assertThat(criteria.offset()).isEqualTo(40);
  }

  @ParameterizedTest
  @ValueSource(strings = {"student", "OTHER", " STUDENT"})
  void unknownTypeIsRejected(String type) {
    assertThat(parse(null, type, null, null).errors())
        .containsExactly(new FieldError("type", "Choose EXTERNAL or STUDENT."));
  }

  @Test
  void unconfiguredOptionIsRejected() {
    assertThat(parse(null, null, "no-such", null).errors())
        .containsExactly(new FieldError("option", "Unknown option."));
  }

  @ParameterizedTest
  @ValueSource(strings = {"0", "-1", "abc", "1.5", "99999999999"})
  void invalidPageIsRejected(String page) {
    assertThat(parse(null, null, null, page).errors())
        .containsExactly(new FieldError("page", "The page must be a number from 1."));
  }

  @Test
  void everyInvalidParameterIsReported() {
    assertThat(parse("x".repeat(101), "X", "y", "0").errors())
        .extracting(FieldError::field)
        .containsExactly("text", "type", "option", "page");
  }

  @Test
  void pageSizeIsTwenty() {
    assertThat(SearchCriteria.PAGE_SIZE).isEqualTo(20);
    assertThat(new SearchCriteria("", Optional.empty(), Optional.empty(), 2).offset()).isEqualTo(20);
  }
}

package si.konferenca.registration.domain;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import org.junit.jupiter.api.Test;

/** Registration, SearchText, RegistrationType and ConferenceOption. */
class RegistrationModelTest {

  private static final UUID ID = UUID.fromString("00000000-0000-4000-8000-000000000001");

  private static RegistrationData data(String organization, String institution) {
    return new RegistrationData(
        RegistrationType.EXTERNAL,
        "Ana",
        "ČEŠNJEVEC",
        "Ana@Example.org",
        organization,
        institution,
        null,
        null,
        List.of("ws-ai"),
        List.of("privacy", "photo"));
  }

  @Test
  void acceptTruncatesTheTimeToMillisecondsAndGivesEveryConsentThen() {
    Instant now = Instant.parse("2026-10-22T10:15:30.123456789Z");

    Registration r = Registration.accept(ID, data("Org", null), now);

    Instant expected = Instant.parse("2026-10-22T10:15:30.123Z");
    assertThat(r.id()).isEqualTo(ID);
    assertThat(r.registeredAt()).isEqualTo(expected);
    assertThat(r.consents())
        .containsExactly(
            new Registration.GivenConsent("privacy", expected),
            new Registration.GivenConsent("photo", expected));
    assertThat(r.type()).isEqualTo(RegistrationType.EXTERNAL);
    assertThat(r.firstName()).isEqualTo("Ana");
    assertThat(r.lastName()).isEqualTo("ČEŠNJEVEC");
    assertThat(r.email()).isEqualTo("Ana@Example.org");
    assertThat(r.organization()).isEqualTo("Org");
    assertThat(r.options()).containsExactly("ws-ai");
  }

  @Test
  void listsAreCopied() {
    List<String> options = new ArrayList<>(List.of("a"));
    RegistrationData d =
        new RegistrationData(
            RegistrationType.STUDENT, "a", "b", "c", null, "i", "p", "s", options, List.of());
    options.add("b");

    assertThat(d.options()).containsExactly("a");
  }

  @Test
  void searchTextJoinsLowerCasedFieldsWithTheSeparator() {
    Registration r = Registration.accept(ID, data("Org\u001FX", null), Instant.EPOCH);

    assertThat(SearchText.of(r))
        .isEqualTo("ana\u001Fčešnjevec\u001Fana@example.org\u001Forgx\u001F");
  }

  @Test
  void searchTextUsesTheStudyInstitution() {
    Registration r = Registration.accept(ID, data(null, "UNI"), Instant.EPOCH);

    assertThat(SearchText.of(r)).endsWith("\u001F\u001Funi");
  }

  @Test
  void normalizeLowerCasesWithoutLocaleAndRemovesTheSeparator() {
    assertThat(SearchText.normalize("ČŠŽ I\u001Fİ")).isEqualTo("čšž i" + "i̇");
  }

  @Test
  void parseAcceptsOnlyExactNames() {
    assertThat(RegistrationType.parse("STUDENT")).contains(RegistrationType.STUDENT);
    assertThat(RegistrationType.parse("EXTERNAL")).contains(RegistrationType.EXTERNAL);
    assertThat(RegistrationType.parse("student")).isEmpty();
    assertThat(RegistrationType.parse(null)).isEmpty();
  }

  @Test
  void optionIsSelectableOnlyWhenActiveAndAvailable() {
    ConferenceOption forStudents =
        new ConferenceOption("o", "O", OptionCategory.OTHER, true, Set.of(RegistrationType.STUDENT));
    ConferenceOption inactive =
        new ConferenceOption("o", "O", OptionCategory.OTHER, false, Set.of(RegistrationType.values()));

    assertThat(forStudents.selectableBy(RegistrationType.STUDENT)).isTrue();
    assertThat(forStudents.selectableBy(RegistrationType.EXTERNAL)).isFalse();
    assertThat(inactive.selectableBy(RegistrationType.STUDENT)).isFalse();
  }

  @Test
  void invalidConfigurationMessageNamesTheProblem() {
    assertThat(new InvalidConfigurationException("x")).hasMessage("Invalid conference configuration: x");
  }
}

