  it.each([
    [400, "{}"],
    [403, '{"message":"https"}'],
    [500, ""],
    [200, "not json"],
  ])("treats %i %s as a failure", async (status, body) => {
    respond(status, body);

    await expect(searchRegistrations(account, filters)).resolves.toEqual({ kind: "failed" });
